        }
    }

    public static void handle(SPChangeSkill msg, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> EpicFightCapabilities.getUnparameterizedEntityPatch(Minecraft.m_91087_().f_91073_.m_6815_(msg.entityId()), PlayerPatch.class).ifPresent(playerpatch -> {
