                SkillContainer skillContainer = playerpatch.getSkill(msg.skillSlot);
                if (skillContainer.getSkill() == msg.skill) {
                    skillContainer.setSkill(null);
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }
}

